func (q *Queries) ListTasksForProject(ctx context.Context, arg ListTasksForProjectParams) ([]Task, error) {
	rows, err := q.db.Query(ctx, listTasksForProject,
		arg.TenantID,
		arg.ProjectID,
		arg.Archived,
		arg.StatusID,
		arg.AssigneeUserID,
		arg.Priority,
		arg.ParentTaskID,
		arg.SprintID,
		arg.BacklogOnly,
		arg.Search,
		arg.CursorCreatedAt,
		arg.CursorID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Task
	for rows.Next() {
		var i Task
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.ProjectID,
			&i.StatusID,
			&i.ParentTaskID,
			&i.Title,
			&i.Description,
			&i.Priority,
			&i.AssigneeUserID,
			&i.CreatedByUserID,
			&i.DueAt,
			&i.CompletedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ArchivedAt,
			&i.StartAt,
			&i.Position,
			&i.EstimateSeconds,
			&i.Recurrence,
			&i.SprintID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

